world node {
    use aap:caps/types@0.1.0.{raw-message, customer-query};

    import aap:caps/inference-llm@0.1.0;

    export run: func(message: raw-message) -> customer-query;
}
```

```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::inference_llm::infer;
use crate::aap::caps::types::Intent;

struct Node;

fn parse_intent(s: &str) -> Intent {
    match s.trim().to_lowercase().as_str() {
        "billing_question" => Intent::BillingQuestion,
        "technical_support" => Intent::TechnicalSupport,
        "account_change" => Intent::AccountChange,
        "general_inquiry" => Intent::GeneralInquiry,
        _ => Intent::Unknown,
    }
}

fn truncate_chars(s: &str, max: usize) -> String {
    if s.chars().count() <= max {
        s.to_string()
    } else {
        s.chars().take(max).collect()
    }
}

impl Guest for Node {
    fn run(message: RawMessage) -> CustomerQuery {
        let system = "You are an intent classifier for customer support messages. \
            Respond with exactly one of: billing_question, technical_support, \
            account_change, general_inquiry, unknown.";
        let intent_raw = infer(system, &message.text, "classify");
        let intent = parse_intent(&intent_raw);

        let question = truncate_chars(&message.text, 512);

        CustomerQuery {
            intent,
            entities: Vec::new(),
            question,
        }
    }
}

export!(Node);
```

